#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_sum.h"

namespace ascend_kernel {

at::Tensor sum(const at::Tensor &self, at::IntArrayRef dim, bool keepdim)
{
    // ---- input validation ----
    TORCH_CHECK(self.dim() > 0, "sum: input must have at least 1 dimension");
    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
                "sum: only float16, float32 and bfloat16 are supported, got ", self.scalar_type());

    at::Tensor x = self.contiguous();
    int64_t dtypeSize = x.element_size();
    if (dtypeSize == 0) { dtypeSize = 1; }

    // ---- parse dim ----
    std::vector<int64_t> dims;
    if (dim.size() == 0) {
        // global reduction
        for (int64_t i = 0; i < x.dim(); ++i) {
            dims.push_back(i);
        }
    } else {
        for (auto d : dim) {
            int64_t nd = d;
            if (nd < 0) nd += x.dim();
            TORCH_CHECK(nd >= 0 && nd < x.dim(), "sum: dim out of range");
            dims.push_back(nd);
        }
    }

    // ---- compute output shape ----
    std::vector<int64_t> outputShape;
    std::vector<bool> reduceMask(x.dim(), false);
    for (auto d : dims) {
        reduceMask[d] = true;
    }
    for (int64_t i = 0; i < x.dim(); ++i) {
        if (reduceMask[i]) {
            if (keepdim) {
                outputShape.push_back(1);
            }
        } else {
            outputShape.push_back(x.size(i));
        }
    }

    // ---- single dim reduction (most common case) ----
    if (dims.size() == 1) {
        int64_t reduceDim = dims[0];
        int64_t reduceLength = x.size(reduceDim);
        int64_t totalLength = x.numel() / reduceLength;

        if (totalLength == 0) {
            return at::zeros(outputShape, x.options());
        }

        // ---- get hardware params ----
        auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
        int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
        uint64_t ubSize;
        ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
        int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

        // ---- alignment ----
        int64_t alignElements = 32 / dtypeSize;
        int64_t reduceLengthAlign = ((reduceLength + alignElements - 1) / alignElements) * alignElements;

        // ---- UB capacity check ----
        int64_t bufferCoefficient = (dtypeSize == 2) ? 16 : 20;
        int64_t maxReduceLength = ubSizeLimit / bufferCoefficient;
        maxReduceLength = (maxReduceLength / alignElements) * alignElements;
        TORCH_CHECK(reduceLengthAlign <= maxReduceLength,
                    "sum: reduceLength ", reduceLength, " exceeds UB capacity (max ", maxReduceLength, ")");

        // ---- reshape to [totalLength, reduceLength] ----
        at::Tensor kernelInput;
        if (reduceDim != x.dim() - 1) {
            // need to permute so reduce dim is last
            std::vector<int64_t> perm;
            for (int64_t i = 0; i < x.dim(); ++i) {
                if (i != reduceDim) perm.push_back(i);
            }
            perm.push_back(reduceDim);
            kernelInput = x.permute(perm).contiguous();
        } else {
            kernelInput = x;
        }
        kernelInput = kernelInput.reshape({totalLength, reduceLength});

        // padding if needed
        at::Tensor paddedInput;
        if (reduceLength != reduceLengthAlign) {
            paddedInput = at::constant_pad_nd(kernelInput, {0, reduceLengthAlign - reduceLength}, 0.0);
            paddedInput = paddedInput.contiguous();
        } else {
            paddedInput = kernelInput;
        }

        at::Tensor kernelOutput = at::empty({totalLength}, x.options());

        // ---- Block level tiling ----
        int64_t usedCoreNum = std::max(int64_t(1), std::min(totalLength, coreNum));
        int64_t formerLength = (totalLength + usedCoreNum - 1) / usedCoreNum;
        int64_t tailLength = formerLength - 1;
        int64_t formerNum = totalLength - tailLength * usedCoreNum;
        if (formerNum <= 0) {
            formerNum = usedCoreNum;
            tailLength = formerLength - 1;
        }
        if (tailLength < 0) {
            tailLength = 0;
            formerNum = totalLength;
        }

        uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

        int64_t isFp16 = (x.scalar_type() == at::kHalf) ? 1 : 0;
        int64_t isBf16 = (x.scalar_type() == at::kBFloat16) ? 1 : 0;

        // Launch kernel based on dtype
        if (x.scalar_type() == at::kFloat) {
            EXEC_KERNEL_CMD(sum_float, blockDim,
                            paddedInput, kernelOutput,
                            totalLength, reduceLength, reduceLengthAlign,
                            formerNum, formerLength, tailLength);
        } else {
            EXEC_KERNEL_CMD(sum_half, blockDim,
                            paddedInput, kernelOutput,
                            totalLength, reduceLength, reduceLengthAlign,
                            formerNum, formerLength, tailLength);
        }

        // ---- reshape output ----
        at::Tensor output = kernelOutput.reshape(outputShape);
        return output;
    }

    // ---- multi-dim reduction: fallback to PyTorch for now ----
    // This should be handled by iterating single-dim reductions
    at::Tensor result = x;
    for (auto d : dims) {
        result = torch::sum(result, d, keepdim);
    }
    return result;
}

}  // namespace ascend_kernel
