18	at::Tensor sum(const at::Tensor &self, at::IntArrayRef dim, bool keepdim)
19	{
20	    // ---- input validation ----
21	    TORCH_CHECK(self.dim() > 0, "sum: input must have at least 1 dimension");
22	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
23	                "sum: only float16, float32 and bfloat16 are supported, got ", self.scalar_type());
24	
25	    at::Tensor x = self.contiguous();
26	    int64_t dtypeSize = x.element_size();
27	    if (dtypeSize == 0) { dtypeSize = 1; }
28	
29	    // ---- parse dim ----
30	    std::vector<int64_t> dims;
31	    if (dim.size() == 0) {
32	        // global reduction: all dims
33	        for (int64_t i = 0; i < x.dim(); ++i) {
34	            dims.push_back(i);
35	        }
36	    } else {
37	        for (auto d : dim) {
38	            int64_t nd = d;
39	            if (nd < 0) nd += x.dim();
40	            TORCH_CHECK(nd >= 0 && nd < x.dim(), "sum: dim out of range");
41	            dims.push_back(nd);
42	        }
43	    }
44	
45	    // ---- compute output shape ----
46	    std::vector<bool> reduceMask(x.dim(), false);
47	    for (auto d : dims) {
48	        reduceMask[d] = true;
49	    }
50	
51	    // ---- multi-dim reduction: iterative single-dim reductions ----
52	    at::Tensor result = x;
53	    int64_t reduceCount = 0;
54	    for (int64_t i = 0; i < x.dim(); ++i) {
55	        if (reduceMask[i]) {
56	            int64_t currentDim = i - reduceCount;
57	            result = sum_single_dim(result, currentDim, keepdim || (reduceCount < static_cast<int64_t>(dims.size()) - 1));
58	            reduceCount++;
59	        }
60	    }
61	
62	    return result;
63	}
64	
65	// Helper: single dimension reduction using AscendC kernel
66	at::Tensor sum_single_dim(const at::Tensor &self, int64_t dim, bool keepdim)
67	{
68	    int64_t reduceDim = dim;
69	    if (reduceDim < 0) reduceDim += self.dim();
70	    TORCH_CHECK(reduceDim >= 0 && reduceDim < self.dim(), "sum_single_dim: dim out of range");
71	
72	    int64_t reduceLength = self.size(reduceDim);
73	    int64_t totalLength = self.numel() / reduceLength;
74	
75	    if (totalLength == 0) {
76	        std::vector<int64_t> outputShape;
77	        for (int64_t i = 0; i < self.dim(); ++i) {
78	            if (i == reduceDim) {
79	                if (keepdim) outputShape.push_back(1);
80	            } else {
81	                outputShape.push_back(self.size(i));
82	            }
83	        }
84	        return at::zeros(outputShape, self.options());
85	    }
86	
87	    at::Tensor x = self.contiguous();
88	    int64_t dtypeSize = x.element_size();
89	    if (dtypeSize == 0) { dtypeSize = 1; }
90	
91	    // ---- get hardware params ----
92	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
93	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
94	    uint64_t ubSize;
95	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
96	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
97	
98	    // ---- alignment ----
99	    int64_t alignElements = 32 / dtypeSize;
100	    int64_t reduceLengthAlign = ((reduceLength + alignElements - 1) / alignElements) * alignElements;
101	
102	    // ---- UB capacity check ----
103	    int64_t bufferCoefficient = (dtypeSize == 2) ? 16 : 20;
104	    int64_t maxReduceLength = ubSizeLimit / bufferCoefficient;
105	    maxReduceLength = (maxReduceLength / alignElements) * alignElements;
106	    TORCH_CHECK(reduceLengthAlign <= maxReduceLength,
107	                "sum: reduceLength ", reduceLength, " exceeds UB capacity (max ", maxReduceLength, ")");
108	
109	    // ---- reshape to [totalLength, reduceLength] ----
110	    at::Tensor kernelInput;
111	    if (reduceDim != x.dim() - 1) {
112	        // permute so reduce dim is last
113	        std::vector<int64_t> perm;
114	        for (int64_t i = 0; i < x.dim(); ++i) {
115	            if (i != reduceDim) perm.push_back(i);
116	        }
117	        perm.push_back(reduceDim);
118	        kernelInput = x.permute(perm).contiguous();
119	    } else {
120	        kernelInput = x;
121	    }
122	    kernelInput = kernelInput.reshape({totalLength, reduceLength});
123	
124	    // padding if needed
125	    at::Tensor paddedInput;
126	    if (reduceLength != reduceLengthAlign) {
127	        paddedInput = at::constant_pad_nd(kernelInput, {0, reduceLengthAlign - reduceLength}, 0.0);
128	        paddedInput = paddedInput.contiguous();
129	    } else {
130	        paddedInput = kernelInput;
131	    }
132	
133	    at::Tensor kernelOutput = at::empty({totalLength}, x.options());
134	
135	    // ---- Block level tiling ----
136	    int64_t usedCoreNum = std::max(int64_t(1), std::min(totalLength, coreNum));
137	    int64_t formerLength = (totalLength + usedCoreNum - 1) / usedCoreNum;
138	    int64_t tailLength = formerLength - 1;
139	    int64_t formerNum = totalLength - tailLength * usedCoreNum;
140	    if (formerNum <= 0) {
141	        formerNum = usedCoreNum;
142	        tailLength = formerLength - 1;
143	    }
144	    if (tailLength < 0) {
145	        tailLength = 0;
146	        formerNum = totalLength;
147	    }
148	
149	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
150	
151	    // Launch kernel based on dtype
152	    if (x.scalar_type() == at::kFloat) {
153	        EXEC_KERNEL_CMD(sum_float, blockDim,
154	                        paddedInput, kernelOutput,
155	                        totalLength, reduceLength, reduceLengthAlign,
156	                        formerNum, formerLength, tailLength);
157	    } else {
158	        // half and bfloat16 both use sum_half kernel
159	        EXEC_KERNEL_CMD(sum_half, blockDim,
160	                        paddedInput, kernelOutput,
161	                        totalLength, reduceLength, reduceLengthAlign,
162	                        formerNum, formerLength, tailLength);
163	    }
164	
165	    // ---- reshape output ----
166	    std::vector<int64_t> outputShape;
167	    for (int64_t i = 0; i < x.dim(); ++i) {
168	        if (i == reduceDim) {
169	            if (keepdim) outputShape.push_back(1);
170	        } else {
171	            outputShape.push_back(self.size(i));
172	        }
173	    }
174	    at::Tensor output = kernelOutput.reshape(outputShape);
175	    return output;
176	}
