 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelSum {
public:
    __aicore__ inline KernelSum() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t totalLength, int64_t reduceLength, int64_t reduceLengthAlign,
                                int64_t formerNum, int64_t formerLength, int64_t tailLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();
        int64_t rowOffset;

        if (blockIdx < formerNum) {
            this->blockRows = formerLength;
            rowOffset = formerLength * blockIdx;
        } else {
            this->blockRows = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            rowOffset = formerLength * formerNum + tailLength * tailIdx;
        }

        xGm.SetGlobalBuffer((__gm__ T *)x + rowOffset * reduceLengthAlign,
                             this->blockRows * reduceLengthAlign);
        yGm.SetGlobalBuffer((__gm__ T *)y + rowOffset,
                             this->blockRows);

        this->reduceLength = reduceLength;
        this->reduceLengthAlign = reduceLengthAlign;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, reduceLengthAlign * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, sizeof(T));

        if constexpr (sizeof(T) == sizeof(half)) {
            pipe.InitBuffer(calcBuf, reduceLengthAlign * sizeof(float));
            pipe.InitBuffer(tmpBuf, 32);
        }
    }

    __aicore__ inline void Process()
    {
        for (int64_t row = 0; row < this->blockRows; ++row) {
            CopyIn(row);
            Compute(row);
            CopyOut(row);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t row)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = this->reduceLength * sizeof(T);
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        AscendC::DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;
        padParams.leftPadding = 0;
        padParams.rightPadding = 0;
        AscendC::DataCopyPad(xLocal, xGm[row * this->reduceLengthAlign], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t row)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // float32: direct compute
            float sum = 0.0f;
            for (int64_t i = 0; i < this->reduceLength; ++i) {
                sum += xLocal.GetValue(i);
            }
            yLocal.SetValue(0, sum);
        } else {
            // fp16/bf16: cast to fp32 then compute
            AscendC::LocalTensor<float> workLocal = calcBuf.Get<float>();
            AscendC::LocalTensor<float> tmpLocal = tmpBuf.Get<float>();

            AscendC::Cast(workLocal, xLocal, AscendC::RoundMode::CAST_NONE, this->reduceLengthAlign);

            float sum = 0.0f;
            for (int64_t i = 0; i < this->reduceLength; ++i) {
                sum += workLocal.GetValue(i);
            }

            tmpLocal.SetValue(0, sum);
            AscendC::Cast(yLocal, tmpLocal, AscendC::RoundMode::CAST_ROUND, 1);
        }

        inQueueX.FreeTensor(xLocal);
        outQueueY.EnQue<T>(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t row)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        AscendC::DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = sizeof(T);
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        AscendC::DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;
        padParams.leftPadding = 0;
        padParams.rightPadding = 0;
        AscendC::DataCopyPad(yGm[row], yLocal, copyParams, padParams);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBuf;
