13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelSum {
17	public:
18	    __aicore__ inline KernelSum() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
21	                                int64_t totalLength, int64_t reduceLength, int64_t reduceLengthAlign,
22	                                int64_t formerNum, int64_t formerLength, int64_t tailLength)
23	    {
24	        int64_t blockIdx = AscendC::GetBlockIdx();
25	        int64_t rowOffset;
26	
27	        if (blockIdx < formerNum) {
28	            this->blockRows = formerLength;
29	            rowOffset = formerLength * blockIdx;
30	        } else {
31	            this->blockRows = tailLength;
32	            int64_t tailIdx = blockIdx - formerNum;
33	            rowOffset = formerLength * formerNum + tailLength * tailIdx;
34	        }
35	
36	        xGm.SetGlobalBuffer((__gm__ T *)x + rowOffset * reduceLengthAlign,
37	                             this->blockRows * reduceLengthAlign);
38	        yGm.SetGlobalBuffer((__gm__ T *)y + rowOffset,
39	                             this->blockRows);
40	
41	        this->reduceLength = reduceLength;
42	        this->reduceLengthAlign = reduceLengthAlign;
43	
44	        pipe.InitBuffer(inQueueX, BUFFER_NUM, reduceLengthAlign * sizeof(T));
45	        pipe.InitBuffer(outQueueY, BUFFER_NUM, sizeof(T));
46	
47	        if constexpr (sizeof(T) == sizeof(half)) {
48	            pipe.InitBuffer(calcBuf, reduceLengthAlign * sizeof(float));
49	            pipe.InitBuffer(tmpBuf, 32);
50	        }
51	    }
52	
53	    __aicore__ inline void Process()
54	    {
55	        for (int64_t row = 0; row < this->blockRows; ++row) {
56	            CopyIn(row);
57	            Compute(row);
58	            CopyOut(row);
59	        }
60	    }
61	
62	private:
63	    __aicore__ inline void CopyIn(int64_t row)
64	    {
65	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
66	        AscendC::DataCopyExtParams copyParams;
67	        copyParams.blockCount = 1;
68	        copyParams.blockLen = this->reduceLength * sizeof(T);
69	        copyParams.srcStride = 0;
70	        copyParams.dstStride = 0;
71	        AscendC::DataCopyPadExtParams<T> padParams;
72	        padParams.isPad = false;
73	        padParams.leftPadding = 0;
74	        padParams.rightPadding = 0;
75	        AscendC::DataCopyPad(xLocal, xGm[row * this->reduceLengthAlign], copyParams, padParams);
76	        inQueueX.EnQue(xLocal);
77	    }
78	
79	    __aicore__ inline void Compute(int64_t row)
80	    {
81	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
82	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
83	
84	        if constexpr (sizeof(T) == sizeof(float)) {
85	            // float32: direct compute
86	            float sum = 0.0f;
87	            for (int64_t i = 0; i < this->reduceLength; ++i) {
88	                sum += xLocal.GetValue(i);
89	            }
90	            yLocal.SetValue(0, sum);
91	        } else {
92	            // fp16/bf16: cast to fp32 then compute
93	            AscendC::LocalTensor<float> workLocal = calcBuf.Get<float>();
94	            AscendC::LocalTensor<float> tmpLocal = tmpBuf.Get<float>();
95	
96	            AscendC::Cast(workLocal, xLocal, AscendC::RoundMode::CAST_NONE, this->reduceLengthAlign);
97	
98	            float sum = 0.0f;
99	            for (int64_t i = 0; i < this->reduceLength; ++i) {
100	                sum += workLocal.GetValue(i);
101	            }
102	
103	            tmpLocal.SetValue(0, sum);
104	            AscendC::Cast(yLocal, tmpLocal, AscendC::RoundMode::CAST_ROUND, 1);
105	        }
106	
107	        inQueueX.FreeTensor(xLocal);
108	        outQueueY.EnQue<T>(yLocal);
109	    }
110	
111	    __aicore__ inline void CopyOut(int64_t row)
112	    {
113	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
114	        AscendC::DataCopyExtParams copyParams;
115	        copyParams.blockCount = 1;
116	        copyParams.blockLen = sizeof(T);
117	        copyParams.srcStride = 0;
118	        copyParams.dstStride = 0;
119	        AscendC::DataCopyPad(yGm[row], yLocal, copyParams);
120	        outQueueY.FreeTensor(yLocal);
121	    }
122	
123	private:
124	    AscendC::TPipe pipe;
125	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
126	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
127	    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBuf;
128	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
129	    AscendC::GlobalTensor<T> xGm, yGm;
130	    int64_t blockRows;
131	    int64_t reduceLength;
132	    int64_t reduceLengthAlign;
133	};
