139	                                                  int64_t tailLength)
140	{
141	    KernelSum<float> op;
142	    op.Init(x, y, totalLength, reduceLength, reduceLengthAlign,
143	            formerNum, formerLength, tailLength);
144	    op.Process();
145	}
