28	at::Tensor sum(const at::Tensor &self, at::IntArrayRef dim, bool keepdim)
29	{
30	    // ---- input validation ----
31	    TORCH_CHECK(self.dim() > 0, "sum: input must have at least 1 dimension");
32	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
33	                "sum: only float16, float32 and bfloat16 are supported, got ", self.scalar_type());
34	
35	    at::Tensor x = self.contiguous();
36	    int64_t dtypeSize = x.element_size();
37	    if (dtypeSize == 0) { dtypeSize = 1; }
38	
39	    // ---- parse dim ----
40	    std::vector<int64_t> dims;
41	    if (dim.size() == 0) {
42	        // global reduction: all dims
43	        for (int64_t i = 0; i < x.dim(); ++i) {
44	            dims.push_back(i);
45	        }
46	    } else {
47	        for (auto d : dim) {
48	            int64_t nd = d;
49	            if (nd < 0) nd += x.dim();
50	            TORCH_CHECK(nd >= 0 && nd < x.dim(), "sum: dim out of range");
51	            dims.push_back(nd);
52	        }
53	    }
54	
55	    // ---- compute output shape ----
56	    std::vector<bool> reduceMask(x.dim(), false);
57	    for (auto d : dims) {
58	        reduceMask[d] = true;
59	    }
60	
61	    // ---- multi-dim reduction: iterative single-dim reductions ----
62	    at::Tensor result = x;
63	    int64_t reduceCount = 0;
64	    for (int64_t i = 0; i < x.dim(); ++i) {
65	        if (reduceMask[i]) {
66	            int64_t currentDim = i - reduceCount;
67	            result = sum_single_dim(result, currentDim, keepdim || (reduceCount < static_cast<int64_t>(dims.size()) - 1));
68	            reduceCount++;
69	        }
70	    }
71	
72	    return result;
73	}
74	
75	// Helper: single dimension reduction using AscendC kernel
76	at::Tensor sum_single_dim(const at::Tensor &self, int64_t dim, bool keepdim)
77	{
78	    int64_t reduceDim = dim;
79	    if (reduceDim < 0) reduceDim += self.dim();
80	    TORCH_CHECK(reduceDim >= 0 && reduceDim < self.dim(), "sum_single_dim: dim out of range");
81	
82	    int64_t reduceLength = self.size(reduceDim);
83	    int64_t totalLength = self.numel() / reduceLength;
84	
85	    if (totalLength == 0) {
86	        std::vector<int64_t> outputShape;
87	        for (int64_t i = 0; i < self.dim(); ++i) {
88	            if (i == reduceDim) {
89	                if (keepdim) outputShape.push_back(1);
90	            } else {
91	                outputShape.push_back(self.size(i));
92	            }
93	        }
94	        return at::zeros(outputShape, self.options());
95	    }
96	
97	    at::Tensor x = self.contiguous();
98	    int64_t dtypeSize = x.element_size();
99	    if (dtypeSize == 0) { dtypeSize = 1; }
100	
101	    // ---- get hardware params ----
102	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
103	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
104	    uint64_t ubSize;
105	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
106	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
107	
108	    // ---- alignment ----
109	    int64_t alignElements = 32 / dtypeSize;
110	    int64_t reduceLengthAlign = ((reduceLength + alignElements - 1) / alignElements) * alignElements;
111	
112	    // ---- UB capacity check ----
113	    int64_t bufferCoefficient = (dtypeSize == 2) ? 16 : 20;
114	    int64_t maxReduceLength = ubSizeLimit / bufferCoefficient;
115	    maxReduceLength = (maxReduceLength / alignElements) * alignElements;
116	    TORCH_CHECK(reduceLengthAlign <= maxReduceLength,
117	                "sum: reduceLength ", reduceLength, " exceeds UB capacity (max ", maxReduceLength, ")");
118	
119	    // ---- reshape to [totalLength, reduceLength] ----
120	    at::Tensor kernelInput;
121	    if (reduceDim != x.dim() - 1) {
122	        // permute so reduce dim is last
123	        std::vector<int64_t> perm;
124	        for (int64_t i = 0; i < x.dim(); ++i) {
125	            if (i != reduceDim) perm.push_back(i);
126	        }
127	        perm.push_back(reduceDim);
128	        kernelInput = x.permute(perm).contiguous();
129	    } else {
130	        kernelInput = x;
131	    }
132	    kernelInput = kernelInput.reshape({totalLength, reduceLength});
133	
134	    // padding if needed
135	    at::Tensor paddedInput;
136	    if (reduceLength != reduceLengthAlign) {
137	        paddedInput = at::constant_pad_nd(kernelInput, {0, reduceLengthAlign - reduceLength}, 0.0);
138	        paddedInput = paddedInput.contiguous();
139	    } else {
140	        paddedInput = kernelInput;
141	    }
142	
143	    at::Tensor kernelOutput = at::empty({totalLength}, x.options());
144	
145	    // ---- Block level tiling ----
146	    int64_t usedCoreNum = std::max(int64_t(1), std::min(totalLength, coreNum));
147	    int64_t formerLength = (totalLength + usedCoreNum - 1) / usedCoreNum;
148	    int64_t tailLength = formerLength - 1;
149	    int64_t formerNum = totalLength - tailLength * usedCoreNum;
150	    if (formerNum <= 0) {
151	        formerNum = usedCoreNum;
152	        tailLength = formerLength - 1;
153	    }
154	    if (tailLength < 0) {
155	        tailLength = 0;
156	        formerNum = totalLength;
157	    }
158	
159	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
160	
161	    // Launch kernel based on dtype
162	    if (x.scalar_type() == at::kFloat) {
163	        EXEC_KERNEL_CMD(sum_float, blockDim,
164	                        paddedInput, kernelOutput,
165	                        totalLength, reduceLength, reduceLengthAlign,
166	                        formerNum, formerLength, tailLength);
167	    } else {
168	        // half and bfloat16 both use sum_half kernel
169	        EXEC_KERNEL_CMD(sum_half, blockDim,
170	                        paddedInput, kernelOutput,
171	                        totalLength, reduceLength, reduceLengthAlign,
172	                        formerNum, formerLength, tailLength);
173	    }
174	
175	    // ---- reshape output ----
176	    std::vector<int64_t> outputShape;
177	    for (int64_t i = 0; i < x.dim(); ++i) {
178	        if (i == reduceDim) {
179	            if (keepdim) outputShape.push_back(1);
180	        } else {
181	            outputShape.push_back(self.size(i));
182	        }
183	    }
184	    at::Tensor output = kernelOutput.reshape(outputShape);
185	    return output;
186	}
187	
188	}  // namespace ascend_kernel
